<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {onBeforeRouteLeave,useRouter} from 'vue-router'
import {useSessionStore} from '@/stores/session'
import {usePhoneChange} from '@/composables/usePhoneChange'
import {phoneNumberValid,phoneChangeStatuses,type PhoneSide} from '@/api/modules/phoneChange'
import ServiceWorkspace from '@/components/ServiceWorkspace.vue'
const session=useSessionStore(),router=useRouter(),ui=usePhoneChange(()=>({token:session.token,accountId:session.account?.id||''}))
const {request,error,notice,busy,loading,loaded,pending,needsLogin}=ui
const oldPhone=ref(''),newPhone=ref(''),code=ref(''),confirmed=ref(false),reconfirmed=ref(false),now=ref(Date.now())
const active=computed(()=>!!request.value&&['AWAITING_OLD','AWAITING_NEW','READY'].includes(request.value.current_status)),side=computed<PhoneSide|null>(()=>request.value?.current_status==='AWAITING_OLD'?'OLD':request.value?.current_status==='AWAITING_NEW'?'NEW':null),challenge=computed(()=>request.value?.challenges.find(c=>c.side===side.value)||null),dirty=computed(()=>!!(oldPhone.value||newPhone.value||code.value)),locked=computed(()=>busy.value||loading.value||!!pending.value),cooldown=computed(()=>Math.max(0,Math.ceil((Math.max(ui.retryAt.value,Date.parse(challenge.value?.resend_after||'')||0)-now.value)/1000))),expired=computed(()=>!!request.value&&Date.parse(request.value.expires_at)<=now.value),canContinue=computed(()=>request.value?.can_continue&&!expired.value&&!locked.value&&now.value>=ui.retryAt.value&&(!ui.conflict.value||reconfirmed.value)),canVerify=computed(()=>canContinue.value&&challenge.value?.current_status==='SENT'&&challenge.value.attempts_remaining>0&&Date.parse(challenge.value.expires_at)>now.value&&/^\d{6}$/.test(code.value))
let allowLeave=false,timer:ReturnType<typeof setInterval>|undefined
function clearInputs(){oldPhone.value=newPhone.value=code.value='';confirmed.value=reconfirmed.value=false}
watch(ui.revision,clearInputs,{flush:'sync'})
watch(()=>[request.value?.id,request.value?.current_status,request.value?.object_version],()=>{code.value='';confirmed.value=false;if(request.value){oldPhone.value=newPhone.value=''}},{flush:'sync'})
watch([oldPhone,newPhone,code],()=>{confirmed.value=false},{flush:'sync'})
async function create(){if(!phoneNumberValid(oldPhone.value)||!phoneNumberValid(newPhone.value)||oldPhone.value===newPhone.value||!confirmed.value)return;await ui.execute('create',{old_phone:oldPhone.value,new_phone:newPhone.value})}
async function send(){if(!side.value||!canContinue.value||cooldown.value>0)return;await ui.execute('send',{side:side.value})}
async function verify(){if(!side.value||!challenge.value||!canVerify.value)return;await ui.execute('verify',{side:side.value,challenge_id:challenge.value.id,code:code.value})}
async function confirm(){if(!confirmed.value)return;if(pending.value?.command==='confirm')await ui.retry(true);else if(canContinue.value&&request.value?.current_status==='READY')await ui.execute('confirm')}
async function cancel(){if(!canContinue.value||!window.confirm('取消本次换号申请，继续使用原号码登录？'))return;await ui.execute('cancel')}
async function login(reason:'recent'|'complete'|'uncertain'){if(busy.value)return;allowLeave=true;clearInputs();if(reason==='complete'||!session.token)session.clearLocal();else await session.logout();await router.replace({path:'/login',query:{redirect:'/me/phone-change',phoneChange:reason}})}
watch(needsLogin,value=>{if(value==='complete')void login('complete')},{flush:'post'})
function leave(){if(allowLeave)return true;if(pending.value||busy.value){notice.value='请先核对原换号请求的结果，再离开本页。';return false}return !dirty.value||window.confirm('本页有尚未提交的号码或验证码。离开将清除这些输入，确认离开？')}
function unload(event:BeforeUnloadEvent){if(!allowLeave&&(pending.value||busy.value||dirty.value)){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(leave)
onMounted(()=>{timer=setInterval(()=>{now.value=Date.now()},1000);window.addEventListener('beforeunload',unload)})
onUnmounted(()=>{if(timer)clearInterval(timer);window.removeEventListener('beforeunload',unload);clearInputs()})
</script>
<template><ServiceWorkspace title="更换登录手机号" intro="更换登录号码后，原账号、订单、作品和机构关系继续保留。" account-only account-context :locked="locked" :dirty="dirty" :error="error" :notice="notice" @ready="ui.load">
 <section v-if="needsLogin==='uncertain'" class="supply-card"><h2>核对换号结果</h2><p>旧登录已失效，换号确认可能已完成。请用新号码登录，再回到本页读取最近结果。</p><button class="primary" @click="login('uncertain')">用新号码登录并核对</button></section>
 <template v-else><section class="supply-card"><h2>开始前核对</h2><p>需要最近 10 分钟内完成短信登录。随后依次验证旧号码与新号码，最后由本人明确确认；申请有效 15 分钟。</p><p>本页操作属于登录账号，与个人或机构办理身份无关。</p><div class="service-actions"><button class="outline" :disabled="busy||loading" @click="ui.load">{{pending?'先核对原换号进度':'重新读取换号进度'}}</button><button v-if="needsLogin==='recent'" class="primary" :disabled="busy" @click="login('recent')">重新短信登录验证身份</button><RouterLink v-if="!pending&&!busy" to="/support/new" class="button-link outline">旧号码无法收短信，提交人工核查</RouterLink></div><p class="service-muted">客服工单用于核查，并不直接完成换绑。</p></section>
 <section v-if="pending" class="service-pending"><p>{{pending.command==='confirm'?'确认结果未核实，不会自动再次提交或跳转登录。':'请求结果尚未核实，已保留原内容和原请求。'}}</p><button v-if="pending.command!=='confirm'" class="outline" :disabled="busy||loading||!pending.checked||now<ui.retryAt.value" @click="ui.retry()">恢复已核对的原请求</button><template v-else-if="pending.checked"><label class="trade-check"><input v-model="confirmed" type="checkbox" :disabled="busy||loading">我已核对服务器仍等待本人确认，继续原确认请求。</label><button class="primary" :disabled="busy||loading||!confirmed" @click="confirm">继续原确认请求</button></template></section>
 <p v-if="loading" role="status">正在读取本账号的换号进度…</p><p v-if="ui.retryAt.value>now" class="supply-warning">请求过于频繁，请等待 {{Math.ceil((ui.retryAt.value-now)/1000)}} 秒后按原进度继续。</p>
 <section v-if="request" class="supply-card"><h2>{{phoneChangeStatuses[request.current_status]}}</h2><dl class="supply-facts"><div><dt>原登录号码</dt><dd>{{request.old_phone_mask}}</dd></div><div><dt>新登录号码</dt><dd>{{request.new_phone_mask}}</dd></div><div><dt>申请到期时间</dt><dd>{{new Date(request.expires_at).toLocaleString()}}</dd></div></dl><p v-if="request.current_status==='COMPLETED'&&!request.requires_relogin" class="supply-notice">已通过新登录恢复原账号，可继续查看原订单、作品和机构关系。</p><RouterLink v-if="request.current_status==='COMPLETED'&&!request.requires_relogin" to="/me/business/contracts" class="button-link outline">查看原账号的业务</RouterLink><p v-if="active&&!request.can_continue" class="supply-warning">这笔申请不属于当前登录会话，请回发起设备继续，或等待申请过期。</p><p v-if="active&&expired" class="supply-warning">申请有效期已到，请重新读取服务器状态。</p><label v-if="ui.conflict.value" class="trade-check"><input v-model="reconfirmed" type="checkbox" :disabled="locked">我已核对最新状态，重新确认本次操作。</label>
 <template v-if="active&&request.can_continue"><form v-if="side" @submit.prevent="verify"><h3>{{side==='OLD'?'验证旧登录号码':'验证新登录号码'}}</h3><p v-if="challenge" class="service-muted">{{ {PENDING:'短信发送处理中',SENT:'短信已发送',UNKNOWN:'短信发送结果未确认，请先读取进度',CONSUMED:'本步验证码已使用',EXPIRED:'本步验证码已过期'}[challenge.current_status] }} · 剩余尝试 {{challenge.attempts_remaining}} 次<span v-if="challenge.current_status==='SENT'"> · 验证码到期 {{new Date(challenge.expires_at).toLocaleTimeString()}}</span></p><button type="button" class="outline" :disabled="!canContinue||cooldown>0" @click="send">{{cooldown>0?`${cooldown} 秒后可重新获取`:'向'+(side==='OLD'?'旧':'新')+'号码发送验证码'}}</button><label class="service-field">此步骤的短信验证码<input v-model="code" data-testid="phone-change-code" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="6" :disabled="locked||!request.can_continue" required></label><button class="primary" :disabled="!canVerify">验证{{side==='OLD'?'旧':'新'}}号码</button></form><div v-else-if="request.current_status==='READY'&&!pending"><h3>最后确认</h3><p>确认后将退出全部旧登录。请使用上方的新号码重新登录；本次不会新建账号。</p><label class="trade-check"><input v-model="confirmed" type="checkbox" :disabled="!canContinue">我已核对 {{request.old_phone_mask}} → {{request.new_phone_mask}}，确认更换登录号码。</label><button class="primary" data-testid="phone-change-confirm" :disabled="!canContinue||!confirmed" @click="confirm">确认更换并重新登录</button></div><button class="outline" :disabled="!canContinue" @click="cancel">取消本次换号申请</button></template></section>
 <form v-if="loaded&&!active&&!request?.requires_relogin" class="supply-card" @submit.prevent="create"><fieldset :disabled="locked||needsLogin==='recent'||now<ui.retryAt.value"><h2>申请更换号码</h2><div class="service-form"><label>当前登录号码<input v-model="oldPhone" data-testid="phone-change-old" type="tel" inputmode="tel" autocomplete="off" maxlength="11" required></label><label>新的登录号码<input v-model="newPhone" data-testid="phone-change-new" type="tel" inputmode="tel" autocomplete="off" maxlength="11" required></label></div><p class="service-muted">新号码不能属于另一账号；页面不会合并或覆盖其他账号。</p><label class="trade-check"><input v-model="confirmed" type="checkbox">两个号码均由我本人使用，确认发起验证。</label><button class="primary" data-testid="phone-change-create" :disabled="!confirmed||!phoneNumberValid(oldPhone)||!phoneNumberValid(newPhone)||oldPhone===newPhone||locked">开始验证两个号码</button></fieldset></form></template>
 </ServiceWorkspace></template>
